.iah-hero .btn-cta{display:inline-flex;align-items:center;gap:8px;padding:17px 30px;border-radius:999px;font-size:15px;font-weight:700;letter-spacing:.02em;background:#4AB7D5;color:#09171F;box-shadow:0 8px 24px rgba(74,183,213,.35);transition:transform .35s cubic-bezier(.22,.61,.36,1), box-shadow .35s cubic-bezier(.22,.61,.36,1), background .35s cubic-bezier(.22,.61,.36,1);border:none;cursor:pointer;font-family:'Montserrat',sans-serif;text-decoration:none;}
.iah-hero .btn-cta:hover{transform:translateY(-2px);box-shadow:0 12px 30px rgba(74,183,213,.45);background:#8DD6E8;}
.iah-hero .scroll-cue{position:absolute;right:16px;bottom:34px;z-index:6;color:#EEF6FA;font-size:11px;letter-spacing:.18em;text-transform:uppercase;opacity:.7;display:flex;flex-direction:column;align-items:center;gap:8px;font-family:'Montserrat',sans-serif;}
.iah-hero .scroll-cue .line{width:1px;height:34px;background:linear-gradient(180deg,#8DD6E8,transparent);animation:iahCueFlow 1.8s cubic-bezier(.22,.61,.36,1) infinite;}
@keyframes iahCueFlow{0%{opacity:.2;}50%{opacity:1;}100%{opacity:.2;}}
@media (prefers-reduced-motion:reduce){
  .iah-hero .hero-media video{display:none;}
  .iah-hero .hero-kicker,.iah-hero .hero-h1,.iah-hero .hero-ctas{animation:none;opacity:1;transform:none;}
  .iah-hero .scroll-cue .line{animation:none;opacity:.6;}
}
@media (max-width:720px){
