<script>
(function(){
  'use strict';
  var video = document.getElementById('iahHeroVideo');

  if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){
    video.removeAttribute('autoplay');
    video.pause();
  }

  function scrollToElementId(elId){
    var el = document.querySelector('.elementor-element-' + elId);
    if(el){ el.scrollIntoView({behavior:'smooth', block:'start'}); }
  }
  document.querySelectorAll('.iah-hero [data-scroll-target]').forEach(function(a){
    a.addEventListener('click', function(e){
      e.preventDefault();
      scrollToElementId(a.getAttribute('data-scroll-target'));
    });
  });
})();
