<script>
(function(){
  function parseNum(str){
    var clean = String(str).replace(/\./g,'').replace(/,/g,'.').trim();
    var n = parseFloat(clean);
    return isNaN(n) ? null : n;
  }
  function formatIt(n){ return Math.round(n).toLocaleString('it-IT'); }
  function animate(el, target){
    var duration = 1600, start = null;
    function step(ts){
      if(!start) start = ts;
      var p = Math.min((ts-start)/duration, 1);
      var eased = 1 - Math.pow(1-p, 3);
      el.textContent = formatIt(target*eased);
      if(p<1) requestAnimationFrame(step); else el.textContent = formatIt(target);
    }
    requestAnimationFrame(step);
  }
  function init(){
    var els = document.querySelectorAll('.iah-counter[data-finalcount]');
    if(!els.length) return;
    if(!('IntersectionObserver' in window)){ return; }
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(entry){
        if(!entry.isIntersecting) return;
        var el = entry.target;
        if(el.dataset.animated) return;
        var target = parseNum(el.dataset.finalcount);
        if(target === null) return;
        el.dataset.animated = '1';
        animate(el, target);
      });
    }, {threshold:0.4});
    els.forEach(function(el){ io.observe(el); });
  }
  if(document.readyState === 'loading'){ document.addEventListener('DOMContentLoaded', init); } else { init(); }
